    SCOPE) printf '%s' 'both files commands' ;;
  esac
}

plugin_hook_on() {
  case "$1" in
    'guard-shell-readability.sh') printf '%s\n' 'bash' 'write' 'edit' 'multi_edit' ;;
  esac
}

